gate ryy(p0) a, b { rx(pi/2) a; rx(pi/2) b; cx a, b; rz(p0) b; cx a, b; rx(-pi/2) a; rx(-pi/2) b; }
gate xx_plus_yy(p0, p1) a, b { rz(-p1) a; rxx(p0/2) a, b; ryy(p0/2) a, b; rz(p1) a; }

qubit[4] q;

ctrl @ iswap q[2], q[1], q[0];
ctrl @ ctrl @ s q[0], q[1], q[2];
negctrl @ ctrl @ ctrl @ r(pi/2, 2*pi/5) q[0], q[2], q[3], q[1];
rx(-1.1) q[2];
ctrl @ ctrl @ r(1.813799364234218, 3*pi/4) q[1], q[3], q[2];
ctrl @ dcx q[0], q[3], q[1];
sdg q[0];
negctrl @ ctrl @ sy q[0], q[1], q[2];
sy q[2];
cp(2*pi/5) q[2], q[0];
ctrl @ negctrl @ rzx(2*pi/5) q[2], q[1], q[0], q[3];
xx_plus_yy(1.813799364234218, 3*pi/4) q[1], q[3];
ctrl @ sqrtswapdg q[1], q[3], q[2];
ccx q[3], q[1], q[0];
id q[0];
negctrl @ U(3*pi/4, 1.813799364234218, 2*pi/5) q[0], q[3];
